import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// MOCKS. THEY TOO ARE INEVITABLE.
const mockCart = {
  items: [{ id: '1', name: 'Scythe Polish', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPayment,
}));

describe('Checkout', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Scythe Polish', price: 29.99 }];
  });

  // THE HAPPY PATH. RARE, BUT BEAUTIFUL.
  it('completes full checkout flow successfully', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });

    render(<Checkout onComplete={onComplete} />);

    // Shipping
    await user.type(screen.getByLabelText(/street address/i), '123 Ankh Street');
    await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'DEATH');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review and Place Order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });

  // VALIDATION. THE UNIVERSE HAS RULES.
  it('displays validation errors for empty shipping fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  // EMPTY CART. THE VOID STARES BACK.
  it('shows empty cart message when no items', () => {
    mockCart.items = [];
    render(<Checkout />);

    expect(screen.getByRole('alert')).toHaveTextContent(/your cart is empty/i);
  });

  // PAYMENT FAILURE. EVEN I FIND THIS DISAPPOINTING.
  it('displays error and allows retry on payment failure', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockRejectedValue(new Error('Card declined'));

    render(<Checkout />);
    // ... navigate to review step ...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });

  // ACCESSIBILITY. ALL SOULS DESERVE ACCESS.
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});
